def process(identity_theft_raw, new_england_states) -> pd.DataFrame:
    from glob import glob

    ne_states = new_england_states['Name'].tolist()

    all_rows = []
    for state in ne_states:
        pattern = f"data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/{state}.csv"
        files = glob(pattern)
        if not files:
            continue
        filepath = files[0]

        # Read entire file as raw lines
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()

        # Find header row index
        header_idx = None
        for i, line in enumerate(lines):
            if 'Metropolitan Area' in line and 'Report' in line:
                header_idx = i
                break

        if header_idx is None:
            continue

        # Parse header
        header_parts = lines[header_idx].strip().split(',')
        metro_col = None
        reports_col = None
        for j, part in enumerate(header_parts):
            if 'Metropolitan Area' in part:
                metro_col = j
            if 'Report' in part:
                reports_col = j

        if metro_col is None or reports_col is None:
            continue

        # Parse data rows
        for line in lines[header_idx + 1:]:
            line = line.strip()
            if not line:
                continue
            if 'Source:' in line or 'Consumer Sentinel' in line:
                continue

            # Handle CSV parsing with potential commas in metro names
            import csv
            parts = list(csv.reader([line]))[0]

            if len(parts) <= max(metro_col, reports_col):
                continue

            metro = parts[metro_col].strip()
            reports_str = parts[reports_col].strip()

            if not metro or metro == 'Metropolitan Area':
                continue

            try:
                reports = int(reports_str.replace(',', ''))
            except:
                continue

            all_rows.append({'State': state, 'Metropolitan_Area': metro, 'Reports': reports})

    return pd.DataFrame(all_rows)

