def process(identity_theft_raw, new_england_states) -> pd.DataFrame:
    import glob

    ne_states = new_england_states['Name'].tolist()

    files = glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv')

    # Map state names to file names
    state_file_map = {}
    for f in files:
        fname = f.split('/')[-1].replace('.csv', '')
        for state in ne_states:
            if fname.lower() == state.lower():
                state_file_map[state] = f

    rows = []
    for state, fpath in state_file_map.items():
        df = pd.read_csv(fpath, header=None, encoding='latin-1')
        # Find the header row
        header_row = None
        for i, row in df.iterrows():
            if any('Metropolitan Area' in str(v) for v in row.values):
                header_row = i
                break
        if header_row is None:
            continue
        # Data starts after header row
        data = df.iloc[header_row+1:].copy()
        data.columns = range(len(data.columns))
        # First col is metro area, second col is reports
        for _, r in data.iterrows():
            area = str(r[0]).strip()
            count = str(r[1]).strip()
            if area and area != 'nan' and count != 'nan':
                # Stop at footer/source rows
                if 'Source:' in area or 'source' in area.lower():
                    break
                try:
                    rows.append({'metro_area': area, 'reports': float(count), 'state': state})
                except:
                    pass

    return pd.DataFrame(rows)

